<?php
require __DIR__.'/../app/bootstrap.php';
require_permission('logs.manage');
require_once __DIR__.'/../app/layout.php';

$view=(string)($_GET['view']??'overview');if(!in_array($view,['overview','activity','locations','logins','settings'],true))$view='overview';
$success=$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{csrf_check();$action=(string)($_POST['action']??'');
        if($action==='save_settings'){
            save_setting('activity_tracking_enabled',isset($_POST['activity_tracking_enabled'])?'1':'0');
            save_setting('activity_request_logging_enabled',isset($_POST['activity_request_logging_enabled'])?'1':'0');
            save_setting('activity_store_raw_ip',isset($_POST['activity_store_raw_ip'])?'1':'0');
            save_setting('activity_trust_cloudflare_ip',isset($_POST['activity_trust_cloudflare_ip'])?'1':'0');
            save_setting('activity_trust_forwarded_ip',isset($_POST['activity_trust_forwarded_ip'])?'1':'0');
            save_setting('ip_location_tracking_enabled',isset($_POST['ip_location_tracking_enabled'])?'1':'0');
            $provider=(string)($_POST['ip_location_provider']??'ipwhois');if(!in_array($provider,['ipwhois','disabled'],true))$provider='disabled';save_setting('ip_location_provider',$provider);
            save_setting('activity_log_retention_days',(string)max(7,min(730,(int)($_POST['activity_log_retention_days']??180))));
            save_setting('ip_location_retention_days',(string)max(7,min(730,(int)($_POST['ip_location_retention_days']??180))));
            save_setting('activity_get_throttle_seconds',(string)max(15,min(600,(int)($_POST['activity_get_throttle_seconds']??60))));
            activity_log_event('logs.settings.updated','security');$success='Log & location settings saved.';
        }elseif($action==='cleanup'){$r=activity_cleanup();$success='Cleanup complete: '.array_sum($r).' old records removed.';}
        elseif($action==='refresh_ip'){$ip=trim((string)($_POST['ip']??''));if(!filter_var($ip,FILTER_VALIDATE_IP))throw new RuntimeException('Enter a valid IP address.');activity_geolocate_ip($ip,true);$success='IP location cache refreshed.';}
    }catch(Throwable $e){$error=$e->getMessage();}
}

$q=trim((string)($_GET['q']??''));$country=trim((string)($_GET['country']??''));$city=trim((string)($_GET['city']??''));$event=trim((string)($_GET['event']??''));$userId=(int)($_GET['user_id']??0);$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));
function logs_filter_sql(array &$params,string $alias='a'): string {global $q,$country,$city,$event,$userId,$from,$to;$w=[];if($q!==''){$w[]="({$alias}.event_name LIKE ? OR {$alias}.route LIKE ? OR {$alias}.ip_address LIKE ? OR {$alias}.city LIKE ? OR {$alias}.country LIKE ?)";$x='%'.$q.'%';array_push($params,$x,$x,$x,$x,$x);}if($country!==''){$w[]="{$alias}.country=?";$params[]=$country;}if($city!==''){$w[]="{$alias}.city=?";$params[]=$city;}if($event!==''){$w[]="{$alias}.event_name=?";$params[]=$event;}if($userId>0){$w[]="{$alias}.user_id=?";$params[]=$userId;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$w[]="{$alias}.created_at>=?";$params[]=$from.' 00:00:00';}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$w[]="{$alias}.created_at<=?";$params[]=$to.' 23:59:59';}return $w?' WHERE '.implode(' AND ',$w):'';}

if(isset($_GET['export'])&&in_array($_GET['export'],['activity','locations'],true)){
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="shahkotpk-'.$_GET['export'].'-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');
    if($_GET['export']==='activity'){$p=[];$where=logs_filter_sql($p,'a');$st=db()->prepare("SELECT a.*,u.name user_name,u.email user_email FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id {$where} ORDER BY a.id DESC LIMIT 10000");$st->execute($p);fputcsv($out,['Time','User','Email','Event','Category','Route','Method','Status','IP','City','Region','Country','Timezone','ISP','Device','Browser','OS']);foreach($st as $r)fputcsv($out,[$r['created_at'],$r['user_name'],$r['user_email'],$r['event_name'],$r['event_category'],$r['route'],$r['method'],$r['status_code'],$r['ip_address'],$r['city'],$r['region_name'],$r['country'],$r['timezone_name'],$r['isp'],$r['device_type'],$r['browser_name'],$r['os_name']]);}
    else{$st=db()->query("SELECT l.*,u.name user_name,u.email user_email FROM user_location_history l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.last_seen_at DESC LIMIT 10000");fputcsv($out,['User','Email','IP','City','Region','Country','Timezone','ISP','ASN','Device','Browser','OS','First Seen','Last Seen','Visits']);foreach($st as $r)fputcsv($out,[$r['user_name'],$r['user_email'],$r['ip_address'],$r['city'],$r['region_name'],$r['country'],$r['timezone_name'],$r['isp'],$r['asn'],$r['device_type'],$r['browser_name'],$r['os_name'],$r['first_seen_at'],$r['last_seen_at'],$r['visit_count']]);}fclose($out);exit;
}

$stats=['today'=>0,'users'=>0,'ips'=>0,'countries'=>0,'failed'=>0,'locations'=>0];
try{$stats['today']=(int)db()->query("SELECT COUNT(*) FROM activity_logs WHERE created_at>=CURDATE()")->fetchColumn();$stats['users']=(int)db()->query("SELECT COUNT(DISTINCT user_id) FROM activity_logs WHERE user_id IS NOT NULL AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)")->fetchColumn();$stats['ips']=(int)db()->query("SELECT COUNT(DISTINCT ip_hash) FROM activity_logs WHERE ip_hash IS NOT NULL AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)")->fetchColumn();$stats['countries']=(int)db()->query("SELECT COUNT(DISTINCT country_code) FROM activity_logs WHERE country_code IS NOT NULL AND country_code<>'' AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)")->fetchColumn();$stats['failed']=(int)db()->query("SELECT COUNT(*) FROM activity_logs WHERE event_name='login.failed' AND created_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR)")->fetchColumn();$stats['locations']=(int)db()->query("SELECT COUNT(*) FROM user_location_history")->fetchColumn();}catch(Throwable $e){}
$topCities=[];$topCountries=[];$recent=[];$locations=[];$logins=[];
try{$topCities=db()->query("SELECT city,country,COUNT(*) total FROM activity_logs WHERE city IS NOT NULL AND city<>'' AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY city,country ORDER BY total DESC LIMIT 10")->fetchAll();$topCountries=db()->query("SELECT country,country_code,COUNT(*) total FROM activity_logs WHERE country IS NOT NULL AND country<>'' AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY country,country_code ORDER BY total DESC LIMIT 10")->fetchAll();}catch(Throwable $e){}
try{$p=[];$where=logs_filter_sql($p,'a');$st=db()->prepare("SELECT a.*,u.name user_name,u.email user_email FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id {$where} ORDER BY a.id DESC LIMIT 250");$st->execute($p);$recent=$st->fetchAll();}catch(Throwable $e){}
try{$st=db()->query("SELECT l.*,u.name user_name,u.email user_email FROM user_location_history l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.last_seen_at DESC LIMIT 250");$locations=$st->fetchAll();}catch(Throwable $e){}
try{$st=db()->query("SELECT e.*,u.name user_name FROM security_login_events e LEFT JOIN users u ON u.id=e.user_id ORDER BY e.id DESC LIMIT 250");$logins=$st->fetchAll();}catch(Throwable $e){}

page_start('Logs & Location History',true);
?>
