<div class="logstats"><div><b><?=number_format($stats['today'])?></b><span>Events Today</span></div><div><b><?=number_format($stats['users'])?></b><span>Users / 30d</span></div><div><b><?=number_format($stats['ips'])?></b><span>Unique IPs / 30d</span></div><div><b><?=number_format($stats['countries'])?></b><span>Countries / 30d</span></div><div class="warn"><b><?=number_format($stats['failed'])?></b><span>Failed Logins / 24h</span></div><div><b><?=number_format($stats['locations'])?></b><span>Location Snapshots</span></div></div>
