<?php if($view==='overview'):?>
<div class="loggrid"><section class="card"><h3>Recent Account Activity</h3><div class="loglist"><?php foreach(array_slice($recent,0,12) as $r):?><div class="logitem"><span class="logdot"></span><div><b><?=e($r['event_name'])?></b><small><?=e($r['user_name']?:'Guest/Security')?> · <?=e($r['route']?:'-')?></small></div><div class="logwhere"><?=e(trim(($r['city']?:'').(($r['city']&&$r['country'])?', ':'').($r['country']?:''))?:'Location unavailable')?><small><?=e($r['created_at'])?></small></div></div><?php endforeach;?></div></section>
<section class="card"><h3>Top Cities · 30 Days</h3><?php foreach($topCities as $r):?><div class="barrow"><span><?=e($r['city'])?><?=!empty($r['country'])?' · '.e($r['country']):''?></span><b><?=number_format((int)$r['total'])?></b></div><?php endforeach;?><?php if(!$topCities):?><p class="muted">City estimates will appear after public-IP account activity is recorded.</p><?php endif;?></section>
<section class="card"><h3>Top Countries · 30 Days</h3><?php foreach($topCountries as $r):?><div class="barrow"><span><?=e($r['country'])?> <small><?=e($r['country_code'])?></small></span><b><?=number_format((int)$r['total'])?></b></div><?php endforeach;?></section>
