<div class="location-cards"><?php foreach($locations as $r):?><article class="loccard"><div class="locicon">⌖</div><div class="locbody"><h4><?=e($r['user_name']?:'User #'.$r['user_id'])?></h4><p><?=e(trim(($r['city']?:'Unknown city').', '.($r['region_name']?:'').', '.($r['country']?:''),', '))?></p><div class="locmeta"><span>IP <code><?=e($r['ip_address']?:'hidden')?></code></span><span><?=e($r['timezone_name']?:'Timezone n/a')?></span><span><?=e($r['isp']?:'ISP n/a')?></span><span><?=e($r['device_type'].' · '.$r['browser_name'].' · '.$r['os_name'])?></span></div><small>First <?=e($r['first_seen_at'])?> · Last <?=e($r['last_seen_at'])?> · <?=number_format((int)$r['visit_count'])?> visits</small></div></article><?php endforeach;?><?php if(!$locations):?><div class="card muted">No location history yet.</div><?php endif;?></div>
